svg.script:
const svg = document.getElementById("svg");
const chip = document.getElementById("chip");
const haloA = document.getElementById("haloA");
const haloB = document.getElementById("haloB");
const state = document.getElementById("state");

let dragging = false;

/* START DRAG ANYWHERE ON CHIP */
chip.addEventListener("mousedown", () => dragging = true);
window.addEventListener("mouseup", () => dragging = false);

/* GLOBAL MOVE (WICHTIG!) */
window.addEventListener("mousemove", (e) => {
  if (!dragging) return;

  const pt = svg.createSVGPoint();
  pt.x = e.clientX;
  pt.y = e.clientY;
  const loc = pt.matrixTransform(svg.getScreenCTM().inverse());

  chip.setAttribute("x", loc.x - 60);
  chip.setAttribute("y", loc.y - 13);

  const overB = (loc.x > 560 && loc.x < 860 && loc.y > 150 && loc.y < 430);

  if (overB) {
    haloA.setAttribute("d","");
    haloB.setAttribute("d","M680 300 A25 25 0 0 0 680 340");
    state.textContent = "VLAN 10 → Component B (REBIND)";
  } else {
    haloA.setAttribute("d","M240 300 A25 25 0 0 0 240 340");
    haloB.setAttribute("d","");
    state.textContent = "VLAN 10 → Component A";
  }
});
